 for flip in [False,True]:
  coords={(x,(-y if flip else y)) for x,y in m}
  for k in range(4):
   # rotate coordinates (x,y)->(y,-x)
   xs=[x for x,y in coords]; ys=[y for x,y in coords]; mnx,mny=min(xs),min(ys)
   norm={(x-mnx,y-mny) for x,y in coords}
   if norm not in out: out.append(norm)
   coords={(y,-x) for x,y in coords}
 return out
